import { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../components/ui/card';
import { Badge } from '../components/ui/badge';
import { Skeleton } from '../components/ui/skeleton';
import { Button } from '../components/ui/button';
import { AlertCircle, Package, RefreshCw, Puzzle, Bot, Webhook, Server, ChevronDown, ChevronRight, Store, ExternalLink } from 'lucide-react';

interface PluginManifest {
  name: string;
  version?: string;
  description?: string;
  author?: {
    name?: string;
    email?: string;
    url?: string;
  };
  keywords?: string[];
  skills?: string;
  agents?: string;
  hooks?: string;
  mcpServers?: string;
}

interface PluginComponents {
  skills: string[];
  agents: string[];
  hasHooks: boolean;
  hasMcp: boolean;
}

interface DiscoveredPlugin {
  name: string;
  version: string;
  description: string;
  scope: 'user' | 'project' | 'local';
  path: string;
  repoPath?: string;
  manifest: PluginManifest;
  components: PluginComponents;
}

interface DiscoveredMarketplace {
  name: string;
  source: string;
  url?: string;
  installLocation: string;
  lastUpdated: string;
  autoUpdate?: boolean;
}

interface PluginsByScope {
  user: DiscoveredPlugin[];
  project: Record<string, DiscoveredPlugin[]>;
  local: Record<string, DiscoveredPlugin[]>;
  marketplaces: DiscoveredMarketplace[];
}

const scopeColors: Record<string, string> = {
  user: 'bg-purple-100 text-purple-800',
  project: 'bg-blue-100 text-blue-800',
  local: 'bg-green-100 text-green-800',
};

const scopeLabels: Record<string, string> = {
  user: 'User',
  project: 'Project',
  local: 'Local',
};

function PluginCard({ plugin }: { plugin: DiscoveredPlugin }) {
  const [expanded, setExpanded] = useState(false);
  const { components } = plugin;
  const hasComponents = components.skills.length > 0 || components.agents.length > 0 || components.hasHooks || components.hasMcp;

  return (
    <Card className="hover:shadow-md transition-shadow">
      <CardHeader className="pb-2">
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-2">
            <Package className="h-5 w-5 text-gray-500" />
            <CardTitle className="text-lg">{plugin.name}</CardTitle>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant="outline">{plugin.version}</Badge>
            <Badge className={scopeColors[plugin.scope]}>{scopeLabels[plugin.scope]}</Badge>
          </div>
        </div>
        {plugin.description && (
          <CardDescription className="mt-2">{plugin.description}</CardDescription>
        )}
      </CardHeader>
      <CardContent>
        {/* Component summary */}
        <div className="flex flex-wrap gap-2 mb-3">
          {components.skills.length > 0 && (
            <Badge variant="secondary" className="flex items-center gap-1">
              <Puzzle className="h-3 w-3" />
              {components.skills.length} skill{components.skills.length > 1 ? 's' : ''}
            </Badge>
          )}
          {components.agents.length > 0 && (
            <Badge variant="secondary" className="flex items-center gap-1">
              <Bot className="h-3 w-3" />
              {components.agents.length} agent{components.agents.length > 1 ? 's' : ''}
            </Badge>
          )}
          {components.hasHooks && (
            <Badge variant="secondary" className="flex items-center gap-1">
              <Webhook className="h-3 w-3" />
              hooks
            </Badge>
          )}
          {components.hasMcp && (
            <Badge variant="secondary" className="flex items-center gap-1">
              <Server className="h-3 w-3" />
              MCP
            </Badge>
          )}
        </div>

        {/* Expandable details */}
        {hasComponents && (
          <div>
            <button
              onClick={() => setExpanded(!expanded)}
              className="flex items-center gap-1 text-sm text-gray-600 hover:text-gray-900"
            >
              {expanded ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
              {expanded ? 'Hide details' : 'Show details'}
            </button>

            {expanded && (
              <div className="mt-3 space-y-2 text-sm">
                {components.skills.length > 0 && (
                  <div>
                    <span className="font-medium text-gray-700">Skills:</span>
                    <div className="flex flex-wrap gap-1 mt-1">
                      {components.skills.map(skill => (
                        <Badge key={skill} variant="outline" className="text-xs">
                          /{skill}
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
                {components.agents.length > 0 && (
                  <div>
                    <span className="font-medium text-gray-700">Agents:</span>
                    <div className="flex flex-wrap gap-1 mt-1">
                      {components.agents.map(agent => (
                        <Badge key={agent} variant="outline" className="text-xs">
                          {agent}
                        </Badge>
                      ))}
                    </div>
                  </div>
                )}
                <div className="text-xs text-gray-500 mt-2">
                  Path: {plugin.path}
                </div>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function PluginScopeSection({
  title,
  plugins,
  emptyMessage
}: {
  title: string;
  plugins: DiscoveredPlugin[];
  emptyMessage: string;
}) {
  if (plugins.length === 0) {
    return (
      <div className="mb-8">
        <h2 className="text-xl font-semibold mb-4">{title}</h2>
        <Card>
          <CardContent className="text-center py-8 text-gray-500">
            {emptyMessage}
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="mb-8">
      <h2 className="text-xl font-semibold mb-4">{title}</h2>
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {plugins.map(plugin => (
          <PluginCard key={`${plugin.scope}-${plugin.path}`} plugin={plugin} />
        ))}
      </div>
    </div>
  );
}

function MarketplaceCard({ marketplace }: { marketplace: DiscoveredMarketplace }) {
  const lastUpdated = new Date(marketplace.lastUpdated).toLocaleDateString();

  return (
    <Card className="hover:shadow-md transition-shadow">
      <CardHeader className="pb-2">
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-2">
            <Store className="h-5 w-5 text-gray-500" />
            <CardTitle className="text-lg">{marketplace.name}</CardTitle>
          </div>
          {marketplace.autoUpdate && (
            <Badge variant="secondary" className="text-xs">Auto-update</Badge>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-2 text-sm">
          <div className="flex items-center gap-2">
            <span className="text-gray-600">Source:</span>
            <Badge variant="outline">{marketplace.source}</Badge>
          </div>
          {marketplace.url && (
            <div className="flex items-center gap-2">
              <span className="text-gray-600">URL:</span>
              <a
                href={marketplace.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-blue-600 hover:underline flex items-center gap-1"
              >
                {marketplace.url.replace(/^https?:\/\//, '').slice(0, 40)}
                <ExternalLink className="h-3 w-3" />
              </a>
            </div>
          )}
          <div className="text-xs text-gray-500">
            Last updated: {lastUpdated}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

function MarketplacesSection({ marketplaces }: { marketplaces: DiscoveredMarketplace[] }) {
  if (marketplaces.length === 0) {
    return (
      <div className="mb-8">
        <h2 className="text-xl font-semibold mb-4">Marketplaces</h2>
        <Card>
          <CardContent className="text-center py-8 text-gray-500">
            No marketplaces registered
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="mb-8">
      <h2 className="text-xl font-semibold mb-4">Marketplaces</h2>
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {marketplaces.map(marketplace => (
          <MarketplaceCard key={marketplace.name} marketplace={marketplace} />
        ))}
      </div>
    </div>
  );
}

export function PluginsPage() {
  const [pluginsByScope, setPluginsByScope] = useState<PluginsByScope | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadPlugins = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await fetch('/api/plugins/by-scope');
      if (!response.ok) {
        throw new Error('Failed to fetch plugins');
      }
      const data = await response.json();
      setPluginsByScope(data);
    } catch (err) {
      console.error('Failed to load plugins:', err);
      setError('Failed to load plugins');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadPlugins();
  }, [loadPlugins]);

  // Flatten project plugins for display
  const projectPlugins = pluginsByScope
    ? Object.values(pluginsByScope.project).flat()
    : [];

  const localPlugins = pluginsByScope
    ? Object.values(pluginsByScope.local).flat()
    : [];

  if (loading) {
    return (
      <div className="p-8">
        <div data-testid="loading-spinner" className="space-y-4">
          <Skeleton className="h-8 w-48" />
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map(i => (
              <Card key={i}>
                <CardHeader>
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-3 w-1/2" />
                </CardHeader>
                <CardContent>
                  <Skeleton className="h-8 w-20" />
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-8">
        <Card className="border-red-200">
          <CardContent className="flex items-center justify-between py-6">
            <div className="flex items-center gap-2">
              <AlertCircle className="h-5 w-5 text-red-500" />
              <span className="text-red-700">{error}</span>
            </div>
            <Button onClick={loadPlugins} variant="outline">
              Retry
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-8 space-y-6">
      {/* Scope key with refresh */}
      <div className="flex items-center justify-between">
        <div className="flex flex-wrap gap-6 text-sm">
          <div className="flex items-center gap-2">
            <Badge className={scopeColors.user}>User</Badge>
            <span className="text-gray-600">~/.claude/plugins/</span>
          </div>
          <div className="flex items-center gap-2">
            <Badge className={scopeColors.project}>Project</Badge>
            <span className="text-gray-600">.claude/plugins/</span>
          </div>
          <div className="flex items-center gap-2">
            <Badge className={scopeColors.local}>Local</Badge>
            <span className="text-gray-600">.claude/local/plugins/</span>
          </div>
        </div>
        <Button onClick={loadPlugins} variant="outline" size="sm" className="flex items-center gap-2">
          <RefreshCw className="h-4 w-4" />
          Refresh
        </Button>
      </div>

      {/* Marketplaces */}
      <MarketplacesSection marketplaces={pluginsByScope?.marketplaces || []} />

      {/* Plugin sections by scope */}
      <PluginScopeSection
        title="User Plugins"
        plugins={pluginsByScope?.user || []}
        emptyMessage="No user-level plugins installed. Install plugins to ~/.claude/plugins/"
      />

      <PluginScopeSection
        title="Project Plugins"
        plugins={projectPlugins}
        emptyMessage="No project-level plugins found. Add plugins to .claude/plugins/ in your repos"
      />

      <PluginScopeSection
        title="Local Plugins"
        plugins={localPlugins}
        emptyMessage="No local plugins found"
      />
    </div>
  );
}
