import { useState, useEffect, useMemo, useCallback } from 'react';
import type { TelemetryEvent, TelemetryTaskRef } from '@magic-ingredients/tiny-brain-core';
import { sseManager, type SSEEvent } from '../services/SSEManager';

interface FixTaskRefInput {
  readonly kind: 'fix';
  readonly fixId: string;
  readonly taskId: string;
}

interface PrdTaskRefInput {
  readonly kind: 'prd';
  readonly prdId: string;
  readonly featureId: string;
  readonly taskId: string;
}

export type TaskRefInput = FixTaskRefInput | PrdTaskRefInput;

interface UseTaskTelemetryResult {
  readonly events: TelemetryEvent[];
  readonly loading: boolean;
  readonly error: string | null;
}

function taskRefsMatch(a: TelemetryTaskRef, b: TelemetryTaskRef): boolean {
  if (a.kind !== b.kind) return false;
  if (a.kind === 'prd' && b.kind === 'prd') {
    return a.prd === b.prd && a.feature === b.feature && a.task === b.task;
  }
  if (a.kind === 'fix' && b.kind === 'fix') {
    return a.fix === b.fix && a.task === b.task;
  }
  return false;
}

function encodeSegment(s: string): string {
  return encodeURIComponent(s);
}

function buildUrl(repoId: string, taskRef: TaskRefInput): string {
  if (taskRef.kind === 'fix') {
    return `/api/repos/${encodeSegment(repoId)}/tasks/fix:${encodeSegment(taskRef.fixId)}/${encodeSegment(taskRef.taskId)}/telemetry`;
  }
  return `/api/repos/${encodeSegment(repoId)}/tasks/prd:${encodeSegment(taskRef.prdId)}/${encodeSegment(taskRef.featureId)}/${encodeSegment(taskRef.taskId)}/telemetry`;
}

function taskRefKey(taskRef: TaskRefInput | null): string {
  if (!taskRef) return '';
  if (taskRef.kind === 'fix') return `fix:${taskRef.fixId}/${taskRef.taskId}`;
  return `prd:${taskRef.prdId}/${taskRef.featureId}/${taskRef.taskId}`;
}

function toTelemetryTaskRef(input: TaskRefInput): TelemetryTaskRef {
  if (input.kind === 'fix') {
    return { kind: 'fix', fix: input.fixId, task: input.taskId };
  }
  return { kind: 'prd', prd: input.prdId, feature: input.featureId, task: input.taskId };
}

export function useTaskTelemetry(repoId: string, taskRef: TaskRefInput | null, enabled: boolean): UseTaskTelemetryResult {
  const [events, setEvents] = useState<TelemetryEvent[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const cacheKey = useMemo(() => taskRefKey(taskRef), [taskRef]);
  const coreRef = useMemo(() => taskRef ? toTelemetryTaskRef(taskRef) : null, [cacheKey]);

  useEffect(() => {
    if (!enabled || !taskRef) return;

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetch(buildUrl(repoId, taskRef))
      .then(async (res) => {
        if (cancelled) return;
        if (!res.ok) {
          const body = await res.json().catch(() => ({}));
          throw new Error(body.error ?? `Failed to fetch telemetry (${res.status})`);
        }
        const data = await res.json();
        setEvents(data.events);
      })
      .catch((err: Error) => {
        if (cancelled) return;
        setEvents([]);
        setError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [repoId, cacheKey, enabled]);

  const handleSSE = useCallback((sseEvent: SSEEvent) => {
    if (sseEvent.type !== 'telemetryChange') return;
    if (sseEvent.repoId !== repoId) return;
    if (!coreRef) return;
    if (!taskRefsMatch(sseEvent.event.taskRef, coreRef)) return;
    setEvents(prev => [...prev, sseEvent.event]);
  }, [repoId, coreRef]);

  useEffect(() => {
    if (!enabled || !coreRef) return;
    const unsubscribe = sseManager.on('telemetryChange', handleSSE);
    return unsubscribe;
  }, [enabled, coreRef, handleSSE]);

  return { events, loading, error };
}
