import React from 'react';
import { BarChart3, Loader2, Trash2 } from 'lucide-react';
import { Button } from './ui/button';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import type { QualityScoresResponse, QualityRunSummary } from '../types';

interface ReadinessHeaderProps {
  data: QualityScoresResponse | null;
  trend?: ReadonlyArray<number>;
  selectedRun?: QualityRunSummary | null;
  onRunQuality?: () => void;
  onDeleteRun?: () => void;
  isRunning?: boolean;
  hasClaudeCli?: boolean;
  isApiKeyLoading?: boolean;
}

const SPARKLINE_W = 80;
const SPARKLINE_H = 24;
const SPARKLINE_PAD = 2;

export function buildSparklinePath(points: ReadonlyArray<number>): string {
  const min = Math.min(...points);
  const max = Math.max(...points);
  const range = max - min || 1;
  const usableW = SPARKLINE_W - SPARKLINE_PAD * 2;
  const usableH = SPARKLINE_H - SPARKLINE_PAD * 2;

  return points
    .map((v, i) => {
      const x = SPARKLINE_PAD + (i / (points.length - 1)) * usableW;
      const y = SPARKLINE_PAD + usableH - ((v - min) / range) * usableH;
      return `${i === 0 ? 'M' : 'L'}${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(' ');
}

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

function formatIssueCount(count: number): string {
  return count === 1 ? '1 issue' : `${count} issues`;
}

export const ReadinessHeader: React.FC<ReadinessHeaderProps> = ({
  data,
  trend: _trend,
  selectedRun,
  onRunQuality,
  onDeleteRun,
  isRunning = false,
  hasClaudeCli = false,
  isApiKeyLoading = false,
}) => {
  if (!data) {
    return (
      <div>
        <div className="flex items-center justify-between">
          <div className="text-sm text-muted-foreground">Not assessed</div>
          {!isApiKeyLoading && onRunQuality && (
            <Tooltip>
              <TooltipTrigger asChild>
                <span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={onRunQuality}
                    disabled={!hasClaudeCli || isRunning}
                    className="flex items-center gap-2"
                    data-testid="run-quality-button"
                  >
                    {isRunning ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <BarChart3 className="h-4 w-4" />
                    )}
                    {isRunning ? 'Running...' : 'Run Quality Analysis'}
                  </Button>
                </span>
              </TooltipTrigger>
              {!hasClaudeCli && (
                <TooltipContent>
                  Claude CLI required - use the /quality skill in Claude Code instead
                </TooltipContent>
              )}
            </Tooltip>
          )}
        </div>
      </div>
    );
  }

  const { readiness } = data;
  return (
    <div>
      {/* Top row: passing dimensions + badge + run button */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-3">
          <span className="text-2xl font-bold">{readiness.passing}/{readiness.total}</span>
          <span className="text-sm text-muted-foreground">
            criteria passing
          </span>
        </div>
        <div className="flex items-center gap-3">
          {!isApiKeyLoading && onRunQuality && (
            <Tooltip>
              <TooltipTrigger asChild>
                <span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={onRunQuality}
                    disabled={!hasClaudeCli || isRunning}
                    className="flex items-center gap-2"
                    data-testid="run-quality-button"
                  >
                    {isRunning ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <BarChart3 className="h-4 w-4" />
                    )}
                    {isRunning ? 'Running...' : 'Run Quality Analysis'}
                  </Button>
                </span>
              </TooltipTrigger>
              {!hasClaudeCli && (
                <TooltipContent>
                  Claude CLI required - use the /quality skill in Claude Code instead
                </TooltipContent>
              )}
            </Tooltip>
          )}
        </div>
      </div>

      {/* Progress bar */}
      <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mb-3">
        <div
          data-testid="readiness-progress-bar"
          className="bg-primary h-2 rounded-full transition-all"
          style={{ width: `${readiness.total > 0 ? (readiness.passing / readiness.total) * 100 : 0}%` }}
        />
      </div>

      {/* Selected run info: date + issue count + delete */}
      {selectedRun && (
        <div className="flex items-center justify-between" data-testid="selected-run-info">
          <div className="flex items-center gap-3">
            <span className="text-sm font-medium text-gray-900 dark:text-gray-100">
              {formatDate(selectedRun.date)}
            </span>
            <span className="text-sm text-gray-500 dark:text-gray-400">
              {formatIssueCount(selectedRun.issueCount)}
            </span>
          </div>
          {onDeleteRun && (
            <button
              onClick={onDeleteRun}
              className="text-gray-400 hover:text-red-500 dark:hover:text-red-400 transition-colors"
              title="Delete this quality run"
              data-testid="delete-run-button"
            >
              <Trash2 className="h-4 w-4" />
            </button>
          )}
        </div>
      )}
    </div>
  );
};
