import { useEffect, useState, useCallback } from 'react';
import { sseManager, SSEEvent } from '../services/SSEManager';
import type { Plan, Task } from '../types';

interface SSEState {
  isConnected: boolean;
  lastEvent: SSEEvent | null;
  plans: Plan[];
  activePlanId: string | null;
  personaId: string;
  libraryConnected: number | null;
}

/**
 * Decorator function to enhance a plan with calculated fields
 */
function decoratePlan(plan: Plan, activePlanId: string | null): Plan {
  const progress = !plan.features || plan.features.length === 0
    ? 0
    : Math.round((plan.features.filter(feature => feature.status === 'completed').length / plan.features.length) * 100);

  // Also ensure featureCount is set
  const featureCount = plan.features?.length || 0;

  // Check if this is the currently active plan
  const isTheCurrentPlan = plan.id === activePlanId;

  return {
    ...plan,
    progress,
    featureCount,
    isTheCurrentPlan
  };
}

/**
 * Decorator function to enhance all plans with calculated fields
 */
function decoratePlans(plans: Plan[], activePlanId: string | null): Plan[] {
  return plans.map(plan => decoratePlan(plan, activePlanId));
}

/**
 * React hook for SSE events with the new SSE Manager
 */
export function useSSE() {
  const [state, setState] = useState<SSEState>({
    isConnected: false,
    lastEvent: null,
    plans: [],
    activePlanId: null,
    personaId: 'default',
    libraryConnected: null
  });

  useEffect(() => {
    // Handle all SSE events
    const unsubscribe = sseManager.on('*', (event: SSEEvent) => {
      console.log('[useSSE] Received event:', event.type, event);
      
      setState(prevState => {
        const newState = { ...prevState, lastEvent: event };
        
        switch (event.type) {
          case 'connected':
            return {
              ...newState,
              isConnected: true,
              libraryConnected: event.libraryConnected
            };
            
          case 'personaChange':
          case 'persona-changed':  // Handle both formats for compatibility
            return {
              ...newState,
              personaId: event.personaId,
              plans: decoratePlans(event.plans || [], event.activePlanId || null),
              activePlanId: event.activePlanId || null
            };
            
          case 'planChange': {
            console.log('[useSSE] Processing plan-change event:', event.eventType || 'legacy', event);

            // Handle granular PRD events
            if (event.eventType && event.prdId) {
              const updatedPlans = [...prevState.plans];
              const planIndex = updatedPlans.findIndex(p => p.id === event.prdId);

              switch (event.eventType) {
                case 'prd:created':
                  // New PRD created - add it with full plan data
                  if (event.plan) {
                    console.log('[useSSE] Adding new PRD:', event.prdId);
                    if (planIndex !== -1) {
                      // Replace if exists (shouldn't happen but handle it)
                      updatedPlans[planIndex] = decoratePlan(event.plan, prevState.activePlanId);
                    } else {
                      // Add new plan
                      updatedPlans.push(decoratePlan(event.plan, prevState.activePlanId));
                    }
                  }
                  break;

                case 'prd:feature:added':
                  // Feature added - update just this feature
                  if (planIndex !== -1 && event.feature) {
                    console.log('[useSSE] Adding feature to PRD:', event.prdId, event.feature.title);
                    const plan = { ...updatedPlans[planIndex] };
                    const features = [...(plan.features || [])];

                    // Add or update feature
                    const featureIndex = features.findIndex(f => f.id === event.feature?.id);
                    if (featureIndex !== -1) {
                      features[featureIndex] = { ...features[featureIndex], ...event.feature };
                    } else {
                      features.push({ ...event.feature, tasks: [] });
                    }

                    plan.features = features;
                    updatedPlans[planIndex] = decoratePlan(plan, prevState.activePlanId);
                  }
                  break;

                case 'prd:feature:updated':
                  // Feature status changed - update just this feature
                  if (planIndex !== -1 && event.feature && updatedPlans[planIndex].features) {
                    console.log('[useSSE] Updating feature in PRD:', event.prdId, event.feature.title, event.delta);
                    const plan = { ...updatedPlans[planIndex] };
                    const features = [...plan.features!];
                    const featureIndex = features.findIndex(f => f.id === event.feature?.id);

                    if (featureIndex !== -1) {
                      features[featureIndex] = { ...features[featureIndex], ...event.feature };
                      plan.features = features;
                      updatedPlans[planIndex] = decoratePlan(plan, prevState.activePlanId);
                    }
                  }
                  break;

                case 'prd:feature:tasks:added':
                  // Tasks added to feature - update just this feature's tasks
                  if (planIndex !== -1 && event.feature && event.tasks && updatedPlans[planIndex].features) {
                    console.log('[useSSE] Adding tasks to feature:', event.prdId, event.feature.title, `+${event.tasks.length} tasks`);
                    const plan = { ...updatedPlans[planIndex] };
                    const features = [...plan.features!];
                    const featureIndex = features.findIndex(f => f.id === event.feature?.id);

                    if (featureIndex !== -1) {
                      const feature = { ...features[featureIndex] };
                      const existingTasks = feature.tasks || [];
                      const newTasks: Task[] = event.tasks
                        .filter(newTask => !existingTasks.some(existing => existing.id === newTask.id))
                        .map(eventTask => ({
                          id: eventTask.id,
                          description: eventTask.description,
                          status: eventTask.status,
                          testCommitSha: eventTask.testCommitSha,
                          commitSha: eventTask.commitSha,
                          refactorCommitSha: eventTask.refactorCommitSha,
                          testCommittedAt: eventTask.testCommittedAt,
                          committedAt: eventTask.committedAt,
                          refactorCommittedAt: eventTask.refactorCommittedAt,
                          createdAt: new Date().toISOString(),
                        }));
                      feature.tasks = [...existingTasks, ...newTasks];
                      features[featureIndex] = feature;
                      plan.features = features;
                      updatedPlans[planIndex] = decoratePlan(plan, prevState.activePlanId);
                    }
                  }
                  break;

                case 'prd:feature:task:completed':
                case 'prd:feature:task:updated':
                  // Task updated - update just this task
                  console.log(`[useSSE] Task update event received:`, {
                    eventType: event.eventType,
                    prdId: event.prdId,
                    featureId: event.feature?.id,
                    taskId: event.task?.id,
                    taskDescription: event.task?.description?.substring(0, 50)
                  });

                  console.log(`[useSSE] Current state:`, {
                    planCount: updatedPlans.length,
                    planIndex,
                    planFound: planIndex !== -1,
                    hasFeatures: planIndex !== -1 && !!updatedPlans[planIndex].features,
                    featureCount: planIndex !== -1 ? updatedPlans[planIndex].features?.length : 0
                  });

                  if (planIndex !== -1 && event.feature && event.task && updatedPlans[planIndex].features) {
                    const eventName = event.eventType === 'prd:feature:task:completed' ? 'completed' : 'updated';
                    console.log(`[useSSE] Task ${eventName}:`, event.prdId, event.feature.title, event.task.description.substring(0, 50));

                    const plan = { ...updatedPlans[planIndex] };
                    const features = [...plan.features!];
                    const featureIndex = features.findIndex(f => f.id === event.feature?.id);

                    console.log(`[useSSE] Looking for feature:`, {
                      searchingForId: event.feature?.id,
                      featureIndex,
                      featureFound: featureIndex !== -1,
                      availableFeatureIds: features.map(f => f.id)
                    });

                    if (featureIndex !== -1) {
                      const feature = { ...features[featureIndex] };
                      const tasks = [...(feature.tasks || [])];
                      const taskIndex = tasks.findIndex(t => t.id === event.task?.id);

                      console.log(`[useSSE] Looking for task:`, {
                        searchingForId: event.task?.id,
                        taskIndex,
                        taskFound: taskIndex !== -1,
                        availableTaskIds: tasks.map(t => t.id),
                        taskCount: tasks.length
                      });

                      if (taskIndex !== -1) {
                        // Merge existing task data with updates from event
                        const oldTask = tasks[taskIndex];
                        tasks[taskIndex] = { ...tasks[taskIndex], ...event.task };

                        console.log(`[useSSE] Task merged:`, {
                          oldStatus: oldTask.status,
                          newStatus: tasks[taskIndex].status,
                          oldTestCommitSha: oldTask.testCommitSha,
                          newTestCommitSha: tasks[taskIndex].testCommitSha,
                          taskId: tasks[taskIndex].id
                        });

                        feature.tasks = tasks;

                        // Also update feature status if provided
                        if (event.feature.status) {
                          feature.status = event.feature.status;
                        }

                        features[featureIndex] = feature;
                        plan.features = features;
                        updatedPlans[planIndex] = decoratePlan(plan, prevState.activePlanId);

                        console.log(`[useSSE] ✅ State updated successfully - plan should re-render`);
                      } else {
                        console.debug(`[useSSE] Task not found in feature tasks array - may be handled by RepoDetailPage`);
                      }
                    } else {
                      console.debug(`[useSSE] Feature not found in plan features array - may be handled by RepoDetailPage`);
                    }
                  } else {
                    // Plan not found in global state - this is OK, RepoDetailPage handles it locally
                    console.debug(`[useSSE] Plan not in global state (handled locally by RepoDetailPage):`, {
                      prdId: event.prdId,
                      planFound: planIndex !== -1
                    });
                  }
                  break;

                default:
                  console.log('[useSSE] Unknown event type:', event.eventType);
              }

              return {
                ...newState,
                plans: updatedPlans,
                personaId: prevState.personaId
              };
            }

            // No granular event data found
            console.warn('[useSSE] Received plan-change event without granular data:', event);
            return newState;
          }
            
          case 'error':
            return {
              ...newState,
              isConnected: false
            };
            
          default:
            return newState;
        }
      });
    });

    return () => {
      unsubscribe();
    };
  }, []);

  const reconnect = useCallback(() => {
    sseManager.reconnect();
  }, []);

  return {
    ...state,
    reconnect
  };
}

/**
 * React hook for specific SSE event types
 */
export function useSSEEvent<T extends SSEEvent>(
  eventType: T['type'],
  callback: (_event: T) => void
) {
  useEffect(() => {
    const unsubscribe = sseManager.on(eventType, (event) => {
      callback(event as T);
    });

    return unsubscribe;
  }, [eventType, callback]);
}

/**
 * Legacy hook for backward compatibility
 */
interface UseSSELegacyProps {
  onUpdate: (_event: SSEEvent) => void;
}

export function useSSELegacy({ onUpdate }: UseSSELegacyProps) {
  useEffect(() => {
    const unsubscribe = sseManager.on('*', onUpdate);
    return unsubscribe;
  }, [onUpdate]);

  return null;
}