import React from 'react';
import FixCard from './FixCard';
import type { Fix } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';

interface FixListProps {
  fixes: Fix[];
  selectedFixId: string | null;
  onSelectFix: (fixId: string) => void;
  reviewPipeline?: PipelineStep[];
}

const FixList: React.FC<FixListProps> = ({ fixes, selectedFixId, onSelectFix, reviewPipeline }) => {
  if (fixes.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">🐛</div>
        <p className="text-text-secondary text-center">No fixes found</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Use /fix skill to create a fix document
        </p>
      </div>
    );
  }

  const handleFixClick = (fixId: string) => {
    console.log('[FixList] Fix clicked:', fixId);
    onSelectFix(fixId);
  };

  // Sort fixes: in_progress first, then not_started, then completed
  // Within each group, sort by severity descending (critical > high > medium > low)
  const statusOrder: Record<string, number> = {
    in_progress: 0,
    not_started: 1,
    completed: 2,
    superseded: 3,
  };

  const severityOrder: Record<string, number> = {
    critical: 0,
    high: 1,
    medium: 2,
    low: 3,
  };

  const sortedFixes = [...fixes].sort((a, b) => {
    const statusA = statusOrder[a.status] ?? 1;
    const statusB = statusOrder[b.status] ?? 1;
    if (statusA !== statusB) return statusA - statusB;

    // Within same status, sort by severity descending
    const sevA = severityOrder[a.severity] ?? 2;
    const sevB = severityOrder[b.severity] ?? 2;
    return sevA - sevB;
  });

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Fixes">
      {sortedFixes.map((fix) => (
        <FixCard
          key={fix.id}
          fix={fix}
          isSelected={fix.id === selectedFixId}
          onClick={() => handleFixClick(fix.id)}
          reviewPipeline={reviewPipeline}
        />
      ))}
    </div>
  );
};

export default FixList;
