import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend,
  CategoryScale,
  LinearScale,
  BarElement,
  Title
} from 'chart.js';

// Register Chart.js components
ChartJS.register(
  ArcElement,
  Tooltip,
  Legend,
  CategoryScale,
  LinearScale,
  BarElement,
  Title
);

// Common chart options for consistent theming
export const getChartOptions = (isDark: boolean): {
  textColor: string;
  gridColor: string;
  backgroundColor: string[];
} => ({
  textColor: isDark ? '#9ca3af' : '#6b7280',
  gridColor: isDark ? '#374151' : '#e5e7eb',
  backgroundColor: [
    '#3b82f6', // blue
    '#10b981', // green
    '#f59e0b', // amber
    '#8b5cf6', // purple
    '#ef4444', // red
    '#06b6d4', // cyan
    '#f97316', // orange
    '#84cc16', // lime
  ]
});