/**
 * Phase Derivation Module
 *
 * Derives TDD phase from task data using SHAs as completion markers.
 * All review/refactor phases are generic — driven by the reviews map
 * and pipeline config. No hardcoded agent names.
 */
/**
 * Returns the ordered list of pipeline phases.
 */
/** Filter a pipeline to only review steps (exclude hook steps) */
export function getReviewSteps(pipeline) {
    return pipeline.filter(s => !s.hook);
}
export function getActivePipeline(config) {
    const phases = ['red'];
    if (!config.combineRedGreenCommits) {
        phases.push('green');
    }
    if (config.reviewPipeline) {
        for (const step of getReviewSteps(config.reviewPipeline)) {
            phases.push(`review:${step.type}`, `refactor:${step.type}`);
        }
    }
    phases.push('complete');
    return phases;
}
/**
 * Derives the current TDD phase by walking the pipeline.
 * The first phase without its completion SHA is the current phase.
 */
export function derivePhase(task, config = { combineRedGreenCommits: false }) {
    if (!task.redStartedAt)
        return 'not_started';
    if (!task.testCommitSha)
        return 'red';
    if (!task.commitSha) {
        return config.combineRedGreenCommits ? 'red' : 'green';
    }
    if (config.reviewPipeline) {
        for (const step of getReviewSteps(config.reviewPipeline)) {
            const record = task.reviews?.[step.type] ?? {};
            if (!record.reviewSha)
                return `review:${step.type}`;
            if (!record.refactorCommitSha)
                return `refactor:${step.type}`;
        }
    }
    return 'complete';
}
/**
 * Checks if a specific phase has its completion SHA set.
 */
export function isPhaseComplete(task, phase) {
    if (phase === 'red')
        return !!task.testCommitSha;
    if (phase === 'green')
        return !!task.commitSha;
    if (phase.startsWith('review:')) {
        const type = phase.slice('review:'.length);
        return !!(task.reviews?.[type]?.reviewSha);
    }
    if (phase.startsWith('refactor:')) {
        const type = phase.slice('refactor:'.length);
        return !!(task.reviews?.[type]?.refactorCommitSha);
    }
    return false;
}
/**
 * Checks if a phase is currently in progress.
 * When config is provided, uses pipeline ordering to ensure only the
 * current phase returns true (not future phases).
 */
export function isPhaseInProgress(task, phase, config) {
    if (phase === 'red')
        return !!task.redStartedAt && !task.testCommitSha;
    if (phase === 'green')
        return !!task.testCommitSha && !task.commitSha;
    if (phase.startsWith('refactor:')) {
        const type = phase.slice('refactor:'.length);
        const record = task.reviews?.[type] ?? {};
        return !!record.reviewSha && !record.refactorCommitSha;
    }
    if (phase.startsWith('review:')) {
        const type = phase.slice('review:'.length);
        const record = task.reviews?.[type] ?? {};
        if (!task.commitSha || record.reviewSha)
            return false;
        // With config, check all prior pipeline stages are done (skip hook steps)
        if (config?.reviewPipeline) {
            for (const priorStep of config.reviewPipeline.filter(s => !s.hook)) {
                if (priorStep.type === type)
                    break;
                const priorRecord = task.reviews?.[priorStep.type] ?? {};
                if (!priorRecord.reviewSha)
                    return false;
                if (!priorRecord.refactorCommitSha)
                    return false;
            }
        }
        return true;
    }
    return false;
}
/**
 * Checks if all pipeline stages are complete.
 */
export function isTaskComplete(task, config = { combineRedGreenCommits: false }) {
    return derivePhase(task, config) === 'complete';
}
/**
 * Returns the duration of a phase in milliseconds.
 */
export function getPhaseDuration(task, phase) {
    if (phase === 'red' && task.redStartedAt && task.redCompletedAt) {
        return dateDiff(task.redStartedAt, task.redCompletedAt);
    }
    if (phase === 'green' && task.greenStartedAt && task.greenCompletedAt) {
        return dateDiff(task.greenStartedAt, task.greenCompletedAt);
    }
    if (phase.startsWith('review:')) {
        const record = task.reviews?.[phase.slice('review:'.length)];
        if (record?.startedAt && record?.completedAt) {
            return dateDiff(record.startedAt, record.completedAt);
        }
    }
    if (phase.startsWith('refactor:')) {
        const record = task.reviews?.[phase.slice('refactor:'.length)];
        if (record?.refactorStartedAt && record?.refactorCompletedAt) {
            return dateDiff(record.refactorStartedAt, record.refactorCompletedAt);
        }
    }
    return undefined;
}
function dateDiff(a, b) {
    const ms = new Date(b).getTime() - new Date(a).getTime();
    return Number.isNaN(ms) ? undefined : ms;
}
/**
 * Returns fractional progress (0–1) for a task.
 */
export function phaseProgress(task, config = { combineRedGreenCommits: false }) {
    const phase = derivePhase(task, config);
    if (phase === 'not_started')
        return 0;
    if (phase === 'complete')
        return 1;
    const pipeline = getActivePipeline(config);
    const totalSteps = pipeline.length;
    if (totalSteps <= 0)
        return 0;
    const currentIndex = pipeline.indexOf(phase);
    if (currentIndex === -1)
        return 0;
    return (currentIndex + 1) / totalSteps;
}
/**
 * Average progress across a list of tasks.
 */
export function computeWeightedProgress(tasks, config = { combineRedGreenCommits: false }) {
    if (tasks.length === 0)
        return 0;
    const sum = tasks.reduce((acc, t) => acc + phaseProgress(t, config), 0);
    return sum / tasks.length;
}
