import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { stringToStep } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';

const FIXED_PHASES: Record<string, { emoji: string; label: string }> = {
  red: { emoji: '\u{1F534}', label: 'Red' },
  green: { emoji: '\u{1F7E2}', label: 'Green' },
  complete: { emoji: '✅', label: 'Complete' },
  refactor: { emoji: '↪️', label: 'Refactor' },
};

const ALIASES: Record<string, string> = {
  'mutation-testing': 'mutation',
};

function resolve(type: string, pipelineSteps?: readonly PipelineStep[]): PipelineStep | undefined {
  if (pipelineSteps) {
    const match = pipelineSteps.find(s => s.type === type);
    if (match) return match;
  }
  const canonical = ALIASES[type] ?? type;
  if (pipelineSteps) {
    const aliasMatch = pipelineSteps.find(s => s.type === canonical);
    if (aliasMatch) return aliasMatch;
  }
  return stringToStep(canonical);
}

export function getStepEmoji(type: string, pipelineSteps?: readonly PipelineStep[]): string {
  const fixed = FIXED_PHASES[type];
  if (fixed) return fixed.emoji;
  return resolve(type, pipelineSteps)?.emoji ?? '\u{1F50D}';
}

export function getStepLabel(type: string, pipelineSteps?: readonly PipelineStep[]): string {
  const fixed = FIXED_PHASES[type];
  if (fixed) return fixed.label;
  return resolve(type, pipelineSteps)?.label ?? type;
}
