import React, { useEffect, useState } from 'react';
import { ListChecks, CheckCircle2 } from 'lucide-react';
import FixDetail from './FixDetail';
import type { StepScoreResponse, Fix } from '../types';

interface QipFixPanelProps {
  readonly steps: ReadonlyArray<StepScoreResponse>;
  readonly qipFixIds: Map<string, string>;
  readonly selectedStepType: string | null;
  readonly onSelectStep: (stepType: string) => void;
  readonly repoId: string;
}

export const QipFixPanel: React.FC<QipFixPanelProps> = ({
  steps,
  qipFixIds,
  selectedStepType,
  onSelectStep,
  repoId,
}) => {
  const [selectedFix, setSelectedFix] = useState<Fix | null>(null);
  const [loading, setLoading] = useState(false);

  // Fetch fix detail when step changes
  useEffect(() => {
    if (!selectedStepType) {
      setSelectedFix(null);
      return;
    }

    const fixId = qipFixIds.get(selectedStepType);
    if (!fixId) {
      setSelectedFix(null);
      return;
    }

    setLoading(true);
    fetch(`/api/repos/${repoId}/fixes/${fixId}`)
      .then(res => res.ok ? res.json() : null)
      .then(data => {
        if (data?.fix) {
          setSelectedFix(data.fix);
        } else {
          setSelectedFix(null);
        }
      })
      .catch(() => setSelectedFix(null))
      .finally(() => setLoading(false));
  }, [selectedStepType, repoId, qipFixIds]);

  return (
    <div className="flex-1 p-4">
      <div className="grid grid-cols-1 lg:grid-cols-[280px_1fr] gap-4">
        {/* Left sidebar: step agent cards */}
        <div className="space-y-3">
          {steps.map(step => {
            const hasQip = qipFixIds.has(step.type);
            const isSelected = selectedStepType === step.type;

            return (
              <div
                key={step.type}
                onClick={() => onSelectStep(step.type)}
                className={`cursor-pointer rounded-lg border p-4 transition-all border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 ${
                  isSelected ? 'ring-2 ring-blue-500' : ''
                }`}
                data-testid="step-card"
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="text-lg">{step.emoji}</span>
                    <span className="font-medium text-sm">{step.label}</span>
                  </div>
                  {hasQip && (
                    <CheckCircle2 className="w-4 h-4 text-blue-500" />
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {/* Right panel: FixDetail for selected QIP */}
        <div className="min-h-[300px]">
          {!selectedStepType && (
            <div className="flex items-center justify-center h-full text-gray-400 dark:text-gray-500">
              <div className="text-center">
                <ListChecks className="w-8 h-8 mx-auto mb-2 opacity-50" />
                <p>Select a step to view its QIP tasks</p>
              </div>
            </div>
          )}

          {selectedStepType && !qipFixIds.has(selectedStepType) && (
            <div className="flex items-center justify-center h-full text-gray-400 dark:text-gray-500">
              <div className="text-center">
                <ListChecks className="w-8 h-8 mx-auto mb-2 opacity-50" />
                <p>No QIP generated for this step yet</p>
                <p className="text-xs mt-1">Click &quot;Fix these issues&quot; on the Run tab to generate one</p>
              </div>
            </div>
          )}

          {loading && (
            <div className="flex items-center justify-center h-full text-gray-400">
              Loading QIP...
            </div>
          )}

          {selectedFix && !loading && (
            <FixDetail fix={selectedFix} repoId={repoId} />
          )}
        </div>
      </div>
    </div>
  );
};
