import React, { useState } from 'react';
import { cn } from '@/lib/utils';
import { Sparkles, Search, CheckCircle2, XCircle, AlertTriangle, Info, Loader2 } from 'lucide-react';
import { SelectableCard } from './ui/selectable-card';
import GradePill from './GradePill';
import type { Skill, SkillValidationResult, SkillValidationCheck } from '../types';

interface SkillListProps {
  skills: Skill[];
  selectedSkillId: string | null;
  onSelectSkill: (skillId: string) => void;
  repoId: string;
}

type ValidationState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; result: SkillValidationResult }
  | { status: 'error'; message: string };

function getCheckStatus(check: SkillValidationCheck): 'pass' | 'warn' | 'fail' | 'info' {
  if (check.passed) {
    return 'pass';
  }
  if (check.severity === 'error') {
    return 'fail';
  }
  if (check.severity === 'warning') {
    return 'warn';
  }
  return 'info';
}

function CheckIcon({ status }: { status: 'pass' | 'warn' | 'fail' | 'info' }) {
  switch (status) {
    case 'pass':
      return <CheckCircle2 className="h-4 w-4 text-green-500 shrink-0" />;
    case 'fail':
      return <XCircle className="h-4 w-4 text-red-500 shrink-0" />;
    case 'warn':
      return <AlertTriangle className="h-4 w-4 text-yellow-500 shrink-0" />;
    case 'info':
      return <Info className="h-4 w-4 text-blue-500 shrink-0" />;
  }
}

interface SkillCardProps {
  skill: Skill;
  isSelected: boolean;
  onClick: () => void;
  repoId: string;
  validationState: ValidationState;
  onAnalyse: () => void;
}

const SkillCard: React.FC<SkillCardProps> = ({ skill, isSelected, onClick, validationState, onAnalyse }) => {
  return (
    <div>
      <SelectableCard isSelected={isSelected} onClick={onClick}>
        <div className="flex items-start gap-3">
          <div className={cn(
            'p-2 rounded-lg',
            isSelected ? 'bg-primary/10' : 'bg-muted'
          )}>
            <Sparkles className="h-4 w-4 text-primary" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <h3 className="font-medium text-sm truncate">{skill.name}</h3>
              {skill.origin && (
                <span
                  className="px-1.5 py-0.5 text-xs rounded-full bg-green-500/10 text-green-600 whitespace-nowrap"
                  title={`Recommended: ${skill.origin.recommendationName} (accepted ${new Date(skill.origin.acceptedAt).toLocaleDateString()})`}
                >
                  Recommended
                </span>
              )}
            </div>
            {skill.description && (
              <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">
                {skill.description}
              </p>
            )}
            <p className="text-xs text-muted-foreground/70 mt-1 font-mono truncate">
              {skill.path}
            </p>
          </div>
          <div className="shrink-0">
            {validationState.status === 'loading' ? (
              <span className="flex items-center gap-1 text-xs text-muted-foreground">
                <Loader2 className="h-3 w-3 animate-spin" />
                Analysing...
              </span>
            ) : (
              <button
                type="button"
                aria-label={`Analyse ${skill.name}`}
                className="flex items-center gap-1 px-2 py-1 text-xs rounded-md border border-border hover:bg-accent transition-colors"
                onClick={(e) => {
                  e.stopPropagation();
                  onAnalyse();
                }}
              >
                <Search className="h-3 w-3" />
                Analyse
              </button>
            )}
          </div>
        </div>
      </SelectableCard>

      {validationState.status === 'success' && (
        <div className="ml-11 mt-1 mb-2 p-3 rounded-lg border border-border bg-card/50 space-y-2">
          <div className="flex items-center gap-2">
            <GradePill grade={validationState.result.grade} score={validationState.result.score} />
          </div>
          {validationState.result.checks.length > 0 && (
            <div className="space-y-1">
              {validationState.result.checks.map((check) => {
                const status = getCheckStatus(check);
                return (
                  <div
                    key={check.id}
                    data-check-status={status}
                    className="flex items-start gap-2 text-xs"
                  >
                    <CheckIcon status={status} />
                    <span className="text-muted-foreground">{check.message}</span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {validationState.status === 'error' && (
        <div className="ml-11 mt-1 mb-2 p-3 rounded-lg border border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-950/30">
          <p className="text-xs text-red-600 dark:text-red-400">{validationState.message}</p>
        </div>
      )}
    </div>
  );
};

const SkillList: React.FC<SkillListProps> = ({
  skills,
  selectedSkillId,
  onSelectSkill,
  repoId,
}) => {
  const [validationStates, setValidationStates] = useState<Record<string, ValidationState>>({});

  const handleAnalyse = async (skillId: string) => {
    setValidationStates((prev) => ({ ...prev, [skillId]: { status: 'loading' } }));

    try {
      const response = await fetch(`/api/repos/${repoId}/skills/${skillId}/validate`, {
        method: 'POST',
      });

      if (!response.ok) {
        const data = await response.json();
        setValidationStates((prev) => ({
          ...prev,
          [skillId]: { status: 'error', message: data.error || 'Validation failed' },
        }));
        return;
      }

      const data = await response.json();
      setValidationStates((prev) => ({
        ...prev,
        [skillId]: { status: 'success', result: data.validation },
      }));
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      setValidationStates((prev) => ({
        ...prev,
        [skillId]: { status: 'error', message },
      }));
    }
  };

  if (skills.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">✨</div>
        <p className="text-muted-foreground text-center">No skills installed</p>
        <p className="text-muted-foreground/70 text-sm text-center mt-2">
          Run <code className="px-1 bg-muted rounded">npx tiny-brain analyse</code> to install skills
        </p>
      </div>
    );
  }

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Installed skills">
      {skills.map((skill) => (
        <SkillCard
          key={skill.id}
          skill={skill}
          isSelected={skill.id === selectedSkillId}
          onClick={() => onSelectSkill(skill.id)}
          repoId={repoId}
          validationState={validationStates[skill.id] || { status: 'idle' }}
          onAnalyse={() => handleAnalyse(skill.id)}
        />
      ))}
    </div>
  );
};

export default SkillList;
